// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2011, "2-3", [{"author":"Б. Иомдин","question":"Переходя через улицу, городские жители часто видят … .","choices":["пчелу","осу","тигра","зебру","лося."],"key":"Г","review":["На городской улице","Вспомни, куда смотришь, когда переходишь дорогу. Под ногами на асфальте бывают чередующиеся светлые и тёмные полосы.","Полосатую разметку перехода называют «зеброй», потому что она напоминает окраску этого животного."]},{"author":"Н. Валеева","question":"Джон угостил Петю яблоком. «Спасибо!» — сказал Петя. Что должен ответить Джон?","choices":["<em>Будь здоров!</em>","<em>Твоё здоровье!</em>","<em>На здоровье!</em>","<em>Доброго здоровья!</em>","<em>Здравия желаю!</em>"],"key":"В","review":["Ответ на благодарность","Петя благодарит за угощение, поэтому ищи ответ со смыслом «ешь с удовольствием».","На «спасибо» за еду отвечают «На здоровье!». А «Будь здоров!» можно сказать, например, когда человек чихнул."]},{"author":"И. Иткин и Л. Фёдорова","question":"50 по-русски — <em>пятьдесят</em>. Название какого числа образовано не так, как <em>пятьдесят</em>?","choices":["60","70","80","90","все эти названия образованы одинаково."],"key":"Г","review":["Названия круглых чисел","Сравни «пятьдесят», «шестьдесят», «семьдесят», «восемьдесят». Начало указывает число десятков, а часть «десят» повторяется.","Число 90 называется «девяносто». В этом слове нет общей для других названий части «десят»."]},{"author":"Б. Иомдин","question":"<em>Навстречу ей выруливает мальчик на велосипеде, стоя на</em> <em>педалях: _____ ему _____</em>. Что мы дважды пропустили в этой фразе из книги Майи Кучерской?","choices":["<em>велик</em>","<em>весело</em>","<em>пора</em>","<em>седло</em>","<em>трудно</em>."],"key":"А","review":["Мальчик на велосипеде","Мальчик стоит на педалях. Возможно, ему неудобно сесть, потому что велосипед слишком большой.","«Вели́к» сначала означает «велосипед», а после слова «ему» — «слишком большой». Получается «велик ему велик»."]},{"author":"И. Рубанов","question":"Задание конкурса 2011 года.\nМиша пошёл в первый класс 1 сентября 2009 года, то есть …","choices":["<em>в прошлом году</em>","<em>в будущем году</em>","<em>в позапрошлом году</em>","<em>в нынешнем году</em>","ни один из вариантов (А)–(Г) не подходит."],"key":"В","review":["Когда Миша пошёл в школу?","Этот вопрос задали на олимпиаде в 2011 году. Отсчитай назад один год: 2010-й был прошлым.","Ещё один шаг назад даёт 2009-й. Это год перед прошлым, то есть позапрошлый."]},{"author":"А. Пиперски","question":"Если взять слово <em>Румыния</em> и отбросить две последние буквы, получится название жителя этой страны: <em>румын</em>. Из названия какой страны можно тем же способом получить название её жителя?","choices":["<em>Венгрия</em>","<em>Англия</em>","<em>Германия</em>","<em>Франция</em>","<em>Испания</em>."],"key":"А","review":["Названия стран и жителей","Убери две последние буквы, «ия», у каждого названия. Выйдут «венгр», «англ», «герман», «франц», «испан».","Из этих слов только «венгр» уже называет жителя страны. В остальных случаях говорят, например, «англичанин», «немец», «француз», «испанец»."]},{"author":"С. Бурлак и А. Сомин","question":"Белорусский и русский языки родственны и очень похожи, но правила письма и чтения в них разные. Если в четырёх из этих слов поставить на месте пропуска букву <em>ы</em>, то получатся слова, которые есть и в русском языке, и в белорусском, а в одном случае получится только белорусское слово. В каком?","choices":["<em>р_ба</em>","<em>л_жа</em>","<em>т_сяча</em>","<em>б_ль</em>","<em>маш_на</em>."],"key":"Д","review":["Буква Ы в двух языках","Подставь «ы» и прочитай: «рыба», «лыжа», «тысяча», «быль», «машына». Первые четыре так и пишут по-русски.","В русском языке действует правило «жи-ши пиши с и», поэтому по-русски «машина». Белорусское «машына» пишут через «ы»."]},{"author":"К. Гилярова","question":"Мама купила яблоки, сливы, клубнику и чернику. Какого варенья она не могла сварить из этих фруктов и ягод?","choices":["<em>яблочного</em>","<em>сливочного</em>","<em>клубничного</em>","<em>черничного</em>","она могла сварить все эти варенья."],"key":"Б","review":["Варенье из фруктов и ягод","Из яблок получается яблочное варенье, из клубники — клубничное, из черники — черничное.","Варенье из слив — сливовое. «Сливочный» относится к сливкам, как в «сливочное масло», поэтому это слово к варенью из слив не подходит."]},{"author":"П. Аркадьев","question":"Какое из приведённых слов может обозначать <strong>не только</strong> музыкальный инструмент?","choices":["<em>флейта</em>","<em>гусли</em>","<em>тромбон</em>","<em>труба</em>","<em>пианино</em>."],"key":"Г","review":["Название инструмента","На флейте, гуслях, тромбоне, трубе и пианино можно играть. Ищи слово, у которого есть ещё обычное значение вне музыки.","Трубой называют и музыкальный инструмент, и полый предмет, по которому течёт, например, вода. Второй смысл слышен в словах «водопроводная труба»."]},{"author":"И. Иткин","question":"Как нельзя закончить предложение <em>Незнайка повесил картину ...</em>?","choices":["<em>на</em> <em>стену</em>","<em>над кровать</em>","<em>под потолком</em>","<em>у стола</em>","<em>в комнате</em>."],"key":"Б","review":["Где Незнайка повесил картину","«На стену» указывает, куда повесили картину. «Под потолком», «у стола» и «в комнате» показывают, где она теперь висит.","С предлогом «над» в этом случае нужен вопрос «над чем?». Правильно «над кроватью», поэтому «над кровать» не подходит."]},{"author":"К. Гилярова","question":"Что не может идти?","choices":["автобус","платье","снег","урок","идти могут и автобус, и платье, и снег, и урок."],"key":"Д","review":["Значения слова «идти»","Автобус идёт по маршруту, снег идёт с неба, урок идёт сорок минут. Во всех случаях слово подходит, даже если никто не шагает.","«Тебе идёт это платье» значит «это платье тебе к лицу». Слово «идти» употребляется и здесь, значит, подходят все четыре примера."]},{"author":"Л. Фёдорова","question":"Слова <em>громкий</em> и <em>тихий</em> составляют пару. Если слова <em>звонкий, резкий, низкий, глухой, высокий</em> разбить на такие пары, одно останется лишним. Какое?","choices":["<em>звонкий</em>","<em>резкий</em>","<em>низкий</em>","<em>глухой</em>","<em>высокий</em>."],"key":"Б","review":["Признаки в парах","Слова «громкий» и «тихий» противоположны. Подбери такие же противоположные пары: «звонкий — глухой», «низкий — высокий».","Для «резкого» можно подобрать «мягкий» или «плавный», но этих слов в списке нет. Поэтому «резкий» остаётся без пары."]},{"author":"А. Сомин","question":"<em>Самолёт — пилот</em>, <em>поезд — машинист</em>, <em>карета</em> — <em>?</em>","choices":["<em>кучер</em>","<em>каретник</em>","<em>водитель</em>","<em>лакей</em>","<em>вожатый</em>."],"key":"А","review":["Кто управляет каретой?","Пилот ведёт самолёт, а машинист ведёт поезд. Для кареты тоже ищи название человека, который ею управляет.","Лошадьми, везущими карету, управляет кучер. Он сидит впереди и держит вожжи."]},{"author":"И. Иткин","question":"На какой из этих вопросов можно получить ответ, заменив в вопросе вторую букву?","choices":["<em>Как?</em>","<em>Куда?</em>","<em>Зачем?</em>","<em>Почему?</em>","<em>Сколько?</em>"],"key":"Д","review":["Вопрос из одного слова","Ищи вопрос, рядом с которым легко поставить ответ такой же длины. На «Сколько?» можно ответить словом «столько» и показать нужное количество.","Сравни «сколько» и «столько» буква за буквой. Поменялась только вторая: «к» стала «т»."]},{"author":"Л. Фёдорова","question":"Четыре из этих пяти фамилий скорее всего происходят от названий пород голубей, которых разводили их хозяева, а одна — нет. Найдите её.","choices":["<em>Чернохвостов</em>","<em>Белокрылов</em>","<em>Синебрюхов</em>","<em>Синезубов</em>","<em>Белобоков</em>."],"key":"Г","review":["Фамилии от пород голубей","Выдели признаки в фамилиях: чёрный хвост, белые крылья, синее брюшко и белые бока. По этим цветам можно различать голубей.","У голубя клюв, и зубов у него нет. Поэтому фамилия Синезубов вряд ли возникла от признака породы голубей."]},{"author":"Л. Фёдорова","question":"Миша увидел имя <em>Мурлыка</em> и сразу догадался, что так зовут кота. А по какому имени нельзя догадаться, кому оно принадлежит?","choices":["<em>Иа-Иа</em>","<em>Пятачок</em>","<em>Каркуша</em>","<em>Степашка</em>","<em>Хрюша</em>."],"key":"Г","review":["Клички и имена героев","В «Иа-Иа» слышен ослик, Каркуша напоминает о карканье вороны, а Хрюша и Пятачок — о голосе и носе поросёнка.","«Степашка» похоже на ласковую форму имени Степан. По звучанию оно не подсказывает, что так назвали зайца."]},{"author":"К. Гилярова","question":"Какое слово в середине предложения пишется с маленькой буквы?","choices":["<em>Россиянин</em>","<em>Александр</em>","<em>Сергеевич</em>","<em>Новгород</em>","все перечисленные слова всегда пишутся с большой буквы."],"key":"А","review":["Заглавная или строчная?","«Александр» — имя, «Сергеевич» — отчество, «Новгород» — название города. Все три пишут с заглавной.","«Россиянин» называет жителя страны. В середине предложения обычно пишут «россиянин» с маленькой буквы, хотя название страны «Россия» начинается с большой."]},{"author":"И. Иткин","question":"Если названия месяцев записать по алфавиту, то первый месяц года, январь, окажется в этом списке последним, двенадцатым. А какой по счёту месяц окажется в этом алфавитном списке первым?","choices":["четвёртый","седьмой","восьмой","девятый","двенадцатый."],"key":"В","review":["Месяцы по алфавиту","Только апрель и август начинаются с первой буквы алфавита. Сравни вторые буквы: у «августа» это «в», у «апреля» — «п».","«В» в алфавите раньше «п», значит, первый в списке август. В календаре он восьмой по счёту."]},{"author":"К. Гилярова и И. Иткин","question":"Герой сказочной повести А. М. Волкова «Волшебник Изумрудного города» Страшила больше всего на свете мечтал, чтобы у него был _________ ум. Он пришёл за помощью к волшебнику Гудвину, и тот наполнил голову Страшилы иголками и булавками. Какое слово мы пропустили?","choices":["<em>гибкий</em>","<em>глубокий</em>","<em>живой</em>","<em>острый</em>","<em>светлый</em>."],"key":"Г","review":["Ум для Страшилы","Гудвин положил Страшиле в голову иголки и булавки. Выбери признак, который подходит и им, и уму.","У иголки острый кончик, а «острый ум» помогает быстро понять и сообразить. Волшебник в шутку понял желание буквально."]},{"author":"Л. Фёдорова","question":"Как правильно закончить фразу:\n<em>Кот в сапогах был доволен: всё шло как</em> ... ?","choices":["<em>по дорожке</em>","<em>по ковру</em>","<em>по сметане</em>","<em>по сыру</em>","<em>по маслу</em>."],"key":"Д","review":["Как шли дела у кота","Кот доволен, значит, всё получалось легко, без помех. Ищи выражение с образом чего-то гладкого и скользкого.","Так говорят «всё шло как по маслу». Масло помогает чему-то скользить, и этот образ передаёт лёгкость."]},{"author":"Е. Муравенко","question":"Мануэла изучает русский язык и уже неплохо говорит по-русски, но вместо звуков [л] и [л’] произносит одинаковый средний звук. Она прочитала пары слов:\n1) <em>лук — люк</em>, 2) <em>угол — уголь</em>, 3) <em>выл</em> — <em>вил</em>.\nВ каких парах слова звучали одинаково?","choices":["в 1 и 2","в 1 и 3","в 2 и 3","только в 1","только в 2."],"key":"А","review":["Как произносит Мануэла","В «лук — люк» отличаются [л] и [л’] в начале, в «угол — уголь» — те же звуки в конце. Если их произнести одинаково, обе пары совпадут.","В «выл — вил» различие сохраняется: в первом слышны [в] и [ы], во втором — [в’] и [и]. Поэтому одинаково звучат только пары 1 и 2."]},{"author":"И. Рубанов","question":"Одна четырёхлетняя девочка, услышав об этом произведении, потом называла его «Тонкий кот». А как оно называется на самом деле?","choices":["«Кот в сапогах»","«Зима в Простоквашино»","«Дон Кихот»","«Кот и повар»","«Руслан и Людмила»."],"key":"В","review":["Как девочка услышала название","В «Тонком коте» прислушайся к кусочкам: «тон», «ки», «кот». Ищи название с похожими звуками в том же порядке.","«Дон Кихот» звучит похоже: «Дон» стал «тон», а в «Кихоте» девочка услышала знакомого «кота»."]},{"author":"Е. Вельмезова","question":"Какое из следующих предложений не может быть ответом на вопрос <em>Мама купила платье вчера?</em>","choices":["— Нет, пальто.","— Нет, бабушка.","— Нет, в понедельник.","— Нет, с друзьями.","— Нет, сшила."],"key":"Г","review":["Что уточняет ответ?","Выделяй по очереди слова в вопросе. «Нет, бабушка» уточняет, кто, «нет, сшила» — что сделала, «нет, пальто» — что именно, «нет, в понедельник» — когда.","«С друзьями» отвечает на вопрос «с кем?». О том, с кем была мама, в вопросе ничего не сказано. Этот ответ с «нет» не исправляет ни одной из названных деталей."]},{"author":"С. Бурлак","question":"В «Обратном словаре русского языка» слова расположены в порядке, который будет алфавитным, если записать каждое слово «задом наперёд»: сначала идут слова, которые заканчиваются на <strong><em>а</em></strong>, потом — те, которые заканчиваются на <strong><em>б</em></strong>, и так далее. В каком порядке в этом словаре расположены слова: <em>богатырь</em>, <em>змей</em>, <em>кощей</em>, <em>царевна</em>, <em>лягушка</em>?","choices":["<em>богатырь</em>, <em>змей</em>, <em>кощей</em>, <em>лягушка</em>, <em>царевна</em>","<em>лягушка</em>, <em>царевна</em>, <em>змей</em>, <em>кощей</em>, <em>богатырь</em>","<em>лягушка</em>, <em>царевна</em>, <em>кощей</em>, <em>змей</em>, <em>богатырь</em>","<em>царевна</em>, <em>лягушка</em>, <em>кощей</em>, <em>змей</em>, <em>богатырь</em>","<em>кощей</em>, <em>богатырь</em>, з<em>мей</em>, <em>царевна</em>, <em>лягушка</em>."],"key":"Б","review":["Слова задом наперёд","Сравни последние буквы. Первыми идут слова на «а», потом на «й», в конце на «ь». На «а» раньше «лягушка»: её предпоследняя «к» стоит перед «н» из «царевны».","Слова «змей» и «кощей» оканчиваются на «-ей». Сравни дальше: «м» раньше «щ». Полный порядок — лягушка, царевна, змей, кощей, богатырь."]},{"author":"А. Сомин","question":"В «грамматической сказке» А. И. Максакова и Г. А. Тумаковой «Исполнение желаний» волшебник обещает зверям исполнить их желания. При этом он использует некоторое правило, и получается, что слон и волк могут загадать по одному желанию, заяц — два, а мартышка — три. Возможно, вы не читали эту сказку, но всё-таки ответьте: сколько желаний могли загадать носорог, ёж и сова?","choices":["два, одно, три","три, одно, два","одно, два, три","три, два, одно","одно, три, два."],"key":"Б","review":["Желания для зверей","Раздели названия на слоги: «слон» и «волк» — один, «за-яц» — два, «мар-ты-шка» — три. Число слогов совпадает с числом желаний.","В «но-со-рог» три слога, в «ёж» один, в «со-ва» два. Поэтому желания распределятся как три, одно, два."]},{"author":"И. Рубанов","question":"Сейчас, описывая заготовку леса, говорят, что его <em>рубят</em>. А были времена, когда говорили, что деревья при заготовке","choices":["<em>молотят</em>","<em>бьют</em>","<em>колотят</em>","<em>режут</em>","<em>секут</em>."],"key":"Д","review":["Старинное слово о лесе","От топора дерево разрубается резкими ударами. Попробуй подобрать старый глагол со значением «рубить ударом».","Подходит «сечь», а для нескольких действующих людей — «секут». След этого слова сохранился в «лесосеке», участке, где рубят лес."]},{"author":"Б. Иомдин и А. Пиперски","question":"Слова <em>перезванивание</em>, <em>перетереть</em>, <em>раскраска</em> обладают одним очень редким свойством. Какое ещё слово обладает этим свойством?","choices":["<em>перерисовать</em>","<em>неестественность</em>","<em>кровообращение</em>","<em>однодневка</em>","<em>приваривать</em>."],"key":"Д","review":["Слова с редким свойством","Выдели одинаковые группы букв, стоящие подряд: «перез-ВАНИ-ВАНИ-е», «п-ЕРЕТ-ЕРЕТ-ь», «РАСК-РАСК-а». Каждый раз повторяются ровно четыре буквы.","В «приваривать» есть «п-РИВА-РИВА-ть» с таким же повтором. В «перерисовать» повторяются только две буквы, «ер», а в «неестественность» — три, «ест»."]},{"author":"Л. Фёдорова","question":"Слова <em>кашне</em>, <em>кашпо</em> и <em>пенсне</em> пришли в русский язык из французского. Во французском языке каждое из них составлено из двух слов. Как выглядят их буквальные переводы?","choices":["спрячь-горшок, прищеми-нос, спрячь-нос","спрячь-нос, спрячь-горшок, прищеми-нос","прищеми-нос, спрячь-горшок, спрячь-нос","спрячь-нос, прищеми-нос, спрячь-горшок","прищеми-нос, спрячь-нос, спрячь-горшок."],"key":"Б","review":["Три французских слова","Кашпо скрывает цветочный горшок, а кашне можно поднять до носа. Общая часть «каш» означает «спрячь». В кашпо «по» — «горшок», а в кашне «не» — «нос».","Пенсне держится на переносице, как будто прищемляет нос. По порядку получается «спрячь нос», «спрячь горшок», «прищеми нос»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
